SELECT s.song_name, s.release_year 
FROM SINGER s 
WHERE s.age = (SELECT MIN(age) FROM SINGER);

SELECT DISTINCT s.Song_Name 
FROM SINGER s 
WHERE s.Age > (SELECT AVG(Age) FROM SINGER);

SELECT DISTINCT s.Song_Name 
FROM SINGER s 
WHERE s.Age > (SELECT AVG(Age) FROM SINGER);

SELECT p.pet_type, p.weight 
FROM PETS p 
WHERE p.age = (SELECT MIN(age) FROM PETS);

SELECT AVG(S.age) 
FROM STUDENT S 
WHERE S.stuid NOT IN (SELECT DISTINCT stuid FROM HAS_PET);

SELECT COUNT(*) 
FROM CARS_DATA 
WHERE ACCELERATE > (
    SELECT MAX(ACCELERATE) 
    FROM CARS_DATA 
    WHERE HORSEPOWER = (
        SELECT MAX(HORSEPOWER) 
        FROM CARS_DATA
    )
);

SELECT COUNT(*) 
FROM CARS_DATA 
WHERE ACCELERATE > (
    SELECT MAX(ACCELERATE) 
    FROM CARS_DATA 
    WHERE HORSEPOWER = (
        SELECT MAX(HORSEPOWER) 
        FROM CARS_DATA
    )
);

SELECT s.name, s.location, s.district
FROM SHOP s
ORDER BY s.number_products DESC;

SELECT template_id, COUNT(*) AS usage_count
FROM DOCUMENTS
GROUP BY template_id;

SELECT DISTINCT t.description
FROM TEMPLATES t
JOIN DOCUMENTS d ON t.template_id = d.template_id;

SELECT T.NAME
FROM TEACHER T
WHERE T.ID NOT IN (
    SELECT DISTINCT CA.TEACHER_ID
    FROM COURSE_ARRANGE CA
);

SELECT AVG(staff_count) AS average_staff
FROM MUSEUM
WHERE YEAR(open_date) < 2009;

SELECT ranking_date, COUNT(DISTINCT tour) AS total_tours
FROM RANKINGS
GROUP BY ranking_date;

SELECT ranking_date, COUNT(DISTINCT tour) AS total_tours
FROM RANKINGS
GROUP BY ranking_date;

SELECT s.FIRST_NAME 
FROM STUDENTS s 
WHERE s.PERMANENT_ADDRESS_ID != s.CURRENT_ADDRESS_ID;

SELECT MIN(release_date) AS first_transcript_date, transcript_id, student_id, degree_program_id, release_date, status
FROM TRANSCRIPTS
WHERE release_date IS NOT NULL;

SELECT Episode 
FROM TV_SERIES 
WHERE series_name = 'Sky Radio';

SELECT nationality, COUNT(*) AS number_of_people
FROM PEOPLE
GROUP BY nationality;

SELECT contestant_no, contestant_name
FROM CONTESTANTS
ORDER BY contestant_name DESC;

SELECT v.VOTE_ID, v.PHONE_NUMBER, acs.STATE 
FROM VOTES v 
JOIN AREA_CODE_STATE acs ON SUBSTR(v.PHONE_NUMBER, 2, 3) = acs.AREA_CODE;

SELECT COUNT(*) 
FROM CONTESTANTS 
WHERE contestant_number NOT IN (SELECT contestant_number FROM VOTES);

SELECT ORCHESTRA.record_company
FROM ORCHESTRA
ORDER BY ORCHESTRA.year_founded DESC;

SELECT c.name
FROM CONDUCTOR c
ORDER BY (c.end_year - c.start_year) DESC;

SELECT h.name
FROM HIGHSCHOOLER h
WHERE EXISTS (
    SELECT 1 FROM FRIEND f WHERE f.student_id = h.id
) AND EXISTS (
    SELECT 1 FROM LIKES l WHERE l.liked_id = h.id
);

SELECT DISTINCT o.state
FROM OWNERS o
INNER JOIN PROFESSIONALS p ON o.state = p.state;

SELECT state FROM OWNERS
INTERSECT
SELECT state FROM PROFESSIONALS;

SELECT first_name FROM (
    SELECT first_name FROM PROFESSIONALS
    UNION
    SELECT first_name FROM OWNERS
) AS human_names
WHERE first_name NOT IN (SELECT name FROM DOGS);

SELECT T.date, P.first_name
FROM TREATMENTS T
JOIN PROFESSIONALS P ON T.professional_id = P.professional_id;

SELECT t.cost, tt.description
FROM TREATMENTS t
JOIN TREATMENT_TYPES tt ON t.treatment_type_id = tt.id;

SELECT d.arriving_date, d.departing_date
FROM DOGS d
JOIN TREATMENTS t ON d.dog_id = t.dog_id;

SELECT d.arriving_date, d.departing_date
FROM DOGS d
JOIN TREATMENTS t ON d.dog_id = t.dog_id;

SELECT COUNT(DISTINCT p.professional_id)
FROM PROFESSIONALS p
JOIN TREATMENTS t ON p.professional_id = t.professional_id;

SELECT first_name, last_name, email 
FROM OWNERS 
WHERE state LIKE '%North%';

SELECT COUNT(*) 
FROM DOGS 
WHERE age < (SELECT AVG(age) FROM DOGS);

SELECT d.dog_name, d.age, d.weight
FROM DOGS d
WHERE d.abandoned = 1;

SELECT DISTINCT s.citizenship
FROM SINGER s
WHERE s.birth_year < 1945 OR s.birth_year > 1955;

SELECT rpt.description 
FROM PROPERTIES p 
JOIN REF_PROPERTY_TYPES rpt ON p.property_type_code = rpt.code;
